ALTER TYPE "LedgerAccountPurpose" ADD VALUE 'RECOVERY_CLAIM_OBLIGATION';
CREATE TABLE "RecoveryClaimObligationBinding"("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"recoveryClaimId" UUID NOT NULL UNIQUE REFERENCES "DisputeRecoveryClaim"(id) ON DELETE RESTRICT,"ledgerAccountId" UUID NOT NULL UNIQUE REFERENCES "LedgerAccount"(id) ON DELETE RESTRICT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "DisputeSellerDeficitOrigination"("id" UUID PRIMARY KEY DEFAULT gen_random_uuid(),"recoveryClaimId" UUID NOT NULL UNIQUE REFERENCES "DisputeRecoveryClaim"(id) ON DELETE RESTRICT,"sellerProfileId" UUID NOT NULL REFERENCES "SellerProfile"(id) ON DELETE RESTRICT,"buyerUserId" UUID NOT NULL REFERENCES "User"(id) ON DELETE RESTRICT,"amountMinor" BIGINT NOT NULL CHECK("amountMinor">0),"currency" TEXT NOT NULL DEFAULT 'BRL' CHECK(currency='BRL'),"ledgerTransactionId" UUID NOT NULL UNIQUE REFERENCES "LedgerTransaction"(id) ON DELETE RESTRICT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "DisputeSellerDeficitOrigination_seller_created_idx" ON "DisputeSellerDeficitOrigination"("sellerProfileId","createdAt",id);
CREATE FUNCTION "reject_aa1_authority_mutation"() RETURNS trigger AS $$ BEGIN RAISE EXCEPTION 'AA1 deficit authority is append-only' USING ERRCODE='55000'; END; $$ LANGUAGE plpgsql;
CREATE FUNCTION "guard_recovery_claim_obligation_binding"() RETURNS trigger AS $$ DECLARE a "LedgerAccount"%ROWTYPE; BEGIN SELECT * INTO a FROM "LedgerAccount" WHERE id=NEW."ledgerAccountId"; IF NOT FOUND THEN RAISE EXCEPTION 'obligation account not found' USING ERRCODE='23503'; END IF; IF a."ownerType"<>'SYSTEM' OR a."ownerId"<>('RECOVERY_CLAIM:'||NEW."recoveryClaimId"::text) OR a."sellerProfileId" IS NOT NULL OR a."accountClass"<>'LIABILITY' OR a.purpose<>'RECOVERY_CLAIM_OBLIGATION' OR a.currency<>'BRL' THEN RAISE EXCEPTION 'obligation authority mismatch' USING ERRCODE='23514'; END IF; NEW."createdAt":=transaction_timestamp()::timestamp(3); RETURN NEW; END; $$ LANGUAGE plpgsql;
CREATE FUNCTION "validate_recovery_obligation_account"() RETURNS trigger AS $$ BEGIN IF NEW.purpose='RECOVERY_CLAIM_OBLIGATION' AND (SELECT count(*) FROM "RecoveryClaimObligationBinding" WHERE "ledgerAccountId"=NEW.id)<>1 THEN RAISE EXCEPTION 'obligation requires claim binding' USING ERRCODE='23514'; END IF; RETURN NULL; END; $$ LANGUAGE plpgsql;
CREATE FUNCTION "guard_dispute_seller_deficit_origination"() RETURNS trigger AS $$
DECLARE c "DisputeRecoveryClaim"%ROWTYPE; t "LedgerTransaction"%ROWTYPE; reserved bigint; entries int; debits int; credits int;
BEGIN SELECT * INTO c FROM "DisputeRecoveryClaim" WHERE id=NEW."recoveryClaimId"; IF NOT FOUND THEN RAISE EXCEPTION 'claim not found' USING ERRCODE='23503'; END IF; PERFORM id FROM "SellerProfile" WHERE id=c."sellerProfileId" FOR UPDATE; SELECT COALESCE(sum("amountMinor"),0) INTO reserved FROM "DisputeRecoveryReservation" WHERE "recoveryClaimId"=c.id; SELECT * INTO t FROM "LedgerTransaction" WHERE id=NEW."ledgerTransactionId";
SELECT count(*),count(*) FILTER(WHERE e.direction='DEBIT' AND a.purpose='SELLER_DEFICIT' AND a."accountClass"='ASSET' AND a."ownerType"='SELLER' AND a."ownerId"=c."sellerProfileId"::text AND a."sellerProfileId"=c."sellerProfileId" AND a.currency='BRL' AND e."amountMinor"=NEW."amountMinor"),count(*) FILTER(WHERE e.direction='CREDIT' AND a.purpose='RECOVERY_CLAIM_OBLIGATION' AND a."accountClass"='LIABILITY' AND a."ownerType"='SYSTEM' AND a.currency='BRL' AND e."amountMinor"=NEW."amountMinor" AND EXISTS(SELECT 1 FROM "RecoveryClaimObligationBinding" b WHERE b."ledgerAccountId"=a.id AND b."recoveryClaimId"=c.id)) INTO entries,debits,credits FROM "LedgerEntry" e JOIN "LedgerAccount" a ON a.id=e."accountId" WHERE e."transactionId"=NEW."ledgerTransactionId";
IF NEW."sellerProfileId"<>c."sellerProfileId" OR NEW."buyerUserId"<>c."buyerUserId" OR NEW.currency<>c.currency OR NEW."amountMinor"<>c."claimAmountMinor"-reserved OR NEW."amountMinor"<=0 OR t.id IS NULL OR t.type<>'DISPUTE_SELLER_DEFICIT_RECOGNIZED' OR t.currency<>'BRL' OR t."referenceType"<>'DisputeRecoveryClaim' OR t."referenceId"<>c.id OR entries<>2 OR debits<>1 OR credits<>1 THEN RAISE EXCEPTION 'deficit origination authority mismatch' USING ERRCODE='23514'; END IF; NEW."createdAt":=transaction_timestamp()::timestamp(3); RETURN NEW; END; $$ LANGUAGE plpgsql;
CREATE FUNCTION "validate_aa1_ledger_correlation"() RETURNS trigger AS $$ BEGIN IF NEW.type='DISPUTE_SELLER_DEFICIT_RECOGNIZED' AND (SELECT count(*) FROM "DisputeSellerDeficitOrigination" WHERE "ledgerTransactionId"=NEW.id)<>1 THEN RAISE EXCEPTION 'AA1 transaction requires origination' USING ERRCODE='23514'; END IF; RETURN NULL; END; $$ LANGUAGE plpgsql;
CREATE TRIGGER "RecoveryClaimObligationBinding_insert_guard" BEFORE INSERT ON "RecoveryClaimObligationBinding" FOR EACH ROW EXECUTE FUNCTION "guard_recovery_claim_obligation_binding"();
CREATE TRIGGER "RecoveryClaimObligationBinding_append_only" BEFORE UPDATE OR DELETE ON "RecoveryClaimObligationBinding" FOR EACH ROW EXECUTE FUNCTION "reject_aa1_authority_mutation"();
CREATE CONSTRAINT TRIGGER "RecoveryClaimObligationAccount_correlation_guard" AFTER INSERT OR UPDATE ON "LedgerAccount" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "validate_recovery_obligation_account"();
CREATE TRIGGER "DisputeSellerDeficitOrigination_insert_guard" BEFORE INSERT ON "DisputeSellerDeficitOrigination" FOR EACH ROW EXECUTE FUNCTION "guard_dispute_seller_deficit_origination"();
CREATE TRIGGER "DisputeSellerDeficitOrigination_append_only" BEFORE UPDATE OR DELETE ON "DisputeSellerDeficitOrigination" FOR EACH ROW EXECUTE FUNCTION "reject_aa1_authority_mutation"();
CREATE CONSTRAINT TRIGGER "AA1Ledger_correlation_guard" AFTER INSERT ON "LedgerTransaction" DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION "validate_aa1_ledger_correlation"();
CREATE FUNCTION "reject_bound_recovery_obligation_mutation"() RETURNS trigger AS $$ BEGIN IF OLD.purpose='RECOVERY_CLAIM_OBLIGATION' THEN RAISE EXCEPTION 'recovery obligation account is immutable' USING ERRCODE='55000'; END IF; RETURN OLD; END; $$ LANGUAGE plpgsql;
CREATE TRIGGER "RecoveryClaimObligationAccount_append_only" BEFORE UPDATE OR DELETE ON "LedgerAccount" FOR EACH ROW EXECUTE FUNCTION "reject_bound_recovery_obligation_mutation"();
